// Opt-in original-vs-compiled-C diagnostic, using the real guest CPU.
//
// This is NOT an OpenWatcom ABI or whole-game replay test. Invoke with an
// unmodified, independently supplied payload and the same payload after
// applying the diagnostic in-place C patch generated by elf_inplace.py.
// No copyrighted payload data is compiled or stored in this program.

#include <unicorn/unicorn.h>

#include <array>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iterator>
#include <limits>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

// All offsets correspond to pinned original payload symbols. In particular,
// the last table entry's signed score lives at g_hiscore_table + 9*25 + 21.
constexpr uint64_t kFunction = 0x432c;
constexpr uint64_t kCurrent = 0x1970a0;
constexpr uint64_t kLast = 0x19719a;
constexpr uint32_t kReturn = 0x3ffe000;
constexpr uint32_t kStack = 0x3fff000;
constexpr size_t kOriginalImageBytes = 1662896;

void check(uc_err error, const char* operation)
{
    if (error != UC_ERR_OK) {
        throw std::runtime_error(std::string(operation) + ": " + uc_strerror(error));
    }
}

std::vector<uint8_t> read_file(const char* filename)
{
    std::ifstream stream(filename, std::ios::binary);
    if (!stream) {
        throw std::runtime_error(std::string("cannot open ") + filename);
    }
    return {std::istreambuf_iterator<char>(stream), std::istreambuf_iterator<char>()};
}

struct Result {
    std::array<uint32_t, 8> regs{};
    uint32_t eip{};
    int memory_writes{};
};

void record_write(uc_engine*, uc_mem_type, uint64_t, int, int64_t, void* context)
{
    ++*static_cast<int*>(context);
}

Result execute(const std::vector<uint8_t>& image, int32_t current, int32_t last)
{
    uc_engine* cpu = nullptr;
    check(uc_open(UC_ARCH_X86, UC_MODE_32, &cpu), "open CPU");
    try {
        check(uc_mem_map(cpu, 0, 0x4000000, UC_PROT_ALL), "map guest RAM");
        check(uc_mem_write(cpu, 0, image.data(), image.size()), "load payload");
        check(uc_mem_write(cpu, kCurrent, &current, sizeof(current)), "set current score");
        check(uc_mem_write(cpu, kLast, &last, sizeof(last)), "set last table score");
        check(uc_mem_write(cpu, kStack, &kReturn, sizeof(kReturn)), "set return PC");

        constexpr std::array<int, 8> ids{
            UC_X86_REG_EAX, UC_X86_REG_EBX, UC_X86_REG_ECX, UC_X86_REG_EDX,
            UC_X86_REG_ESI, UC_X86_REG_EDI, UC_X86_REG_EBP, UC_X86_REG_ESP};
        const std::array<uint32_t, 8> initial{
            0x10203040, 0x21324354, 0x32435465, 0x43546576,
            0x54657687, 0x65768798, 0x768798a9, kStack};
        for (size_t i = 0; i < ids.size(); ++i) {
            check(uc_reg_write(cpu, ids[i], &initial[i]), "initial registers");
        }
        uint32_t flags = 0x202;
        check(uc_reg_write(cpu, UC_X86_REG_EFLAGS, &flags), "initial flags");

        Result result;
        uc_hook writes{};
        check(uc_hook_add(cpu, &writes, UC_HOOK_MEM_WRITE,
                          reinterpret_cast<void*>(record_write),
                          &result.memory_writes, 1, 0), "memory-write hook");
        check(uc_emu_start(cpu, kFunction, kReturn, 0, 64), "run function");
        for (size_t i = 0; i < ids.size(); ++i) {
            check(uc_reg_read(cpu, ids[i], &result.regs[i]), "output registers");
        }
        check(uc_reg_read(cpu, UC_X86_REG_EIP, &result.eip), "return PC");
        if (result.eip != kReturn || result.regs[7] != kStack + 4 ||
            result.memory_writes != 0) {
            throw std::runtime_error("guest did not return without memory writes");
        }
        check(uc_close(cpu), "close CPU");
        return result;
    } catch (...) {
        uc_close(cpu);
        throw;
    }
}

} // namespace

int main(int argc, char** argv)
{
    if (argc != 3) {
        std::fprintf(stderr, "usage: %s ORIGINAL_PAYLOAD PATCHED_PAYLOAD\n", argv[0]);
        return 2;
    }
    try {
        const auto original = read_file(argv[1]);
        const auto patched = read_file(argv[2]);
        if (original.size() != kOriginalImageBytes || patched.size() != original.size()) {
            throw std::runtime_error("expected matching EF2000 payload image sizes");
        }
        struct Case { int32_t current; int32_t last; const char* name; };
        constexpr Case cases[]{
            {0, 0, "zero_tie"}, {101, 100, "positive_greater"},
            {100, 101, "positive_less"}, {-1, -1, "negative_tie"},
            {-2, -3, "negative_greater"}, {-3, -2, "negative_less"},
            {std::numeric_limits<int32_t>::min(), std::numeric_limits<int32_t>::max(), "min_max"},
            {std::numeric_limits<int32_t>::max(), std::numeric_limits<int32_t>::min(), "max_min"},
            {-1, 0, "minus_one_zero"}, {0, -1, "zero_minus_one"},
        };
        for (const auto& test : cases) {
            const Result reference = execute(original, test.current, test.last);
            const Result candidate = execute(patched, test.current, test.last);
            if (reference.regs != candidate.regs || reference.eip != candidate.eip ||
                (reference.regs[0] & 0xff) != static_cast<uint32_t>(test.current > test.last)) {
                throw std::runtime_error(std::string(test.name) + ": differential mismatch");
            }
            std::printf("%s: PASS AL=%u\n", test.name, reference.regs[0] & 0xff);
        }
        return 0;
    } catch (const std::exception& error) {
        std::fprintf(stderr, "guest hiscore differential failed: %s\n", error.what());
        return 1;
    }
}
